 public readonly struct TerrainCellBounds {public readonly double MinX,MinZ,MaxX,MaxZ;public TerrainCellBounds(double x0,double z0,double x1,double z1){if(!TerrainFieldLimits.Finite(x0)||!TerrainFieldLimits.Finite(z0)||!TerrainFieldLimits.Finite(x1)||!TerrainFieldLimits.Finite(z1)||x1<=x0||z1<=z0||x1-x0>32||z1-z0>32||x0!=Math.Round(x0)||z0!=Math.Round(z0)||x1!=Math.Round(x1)||z1!=Math.Round(z1))throw new ArgumentException("Explicit32m-or-smaller integerworld cellbounds");MinX=x0;MinZ=z0;MaxX=x1;MaxZ=z1;}public double Width=>MaxX-MinX;public double Depth=>MaxZ-MinZ;public static TerrainCellBounds Global32(int x,int z)=>new TerrainCellBounds(x*32.0,z*32.0,(x+1)*32.0,(z+1)*32.0);}
 public readonly struct PreciseTerrainBorderKey:IEquatable<PreciseTerrainBorderKey>{public readonly int Axis;public readonly double FixedWorld,AlongMin,AlongMax;public PreciseTerrainBorderKey(int axis,double fixedWorld,double min,double max){if((axis!=0&&axis!=1)||!TerrainFieldLimits.Finite(fixedWorld)||!TerrainFieldLimits.Finite(min)||!TerrainFieldLimits.Finite(max)||min!=Math.Round(min)||max!=Math.Round(max)||fixedWorld!=Math.Round(fixedWorld)||max<=min||max-min>32)throw new ArgumentException("Canonical explicit borderbounds");Axis=axis;FixedWorld=fixedWorld;AlongMin=min;AlongMax=max;}public bool Equals(PreciseTerrainBorderKey o)=>Axis==o.Axis&&FixedWorld==o.FixedWorld&&AlongMin==o.AlongMin&&AlongMax==o.AlongMax;public override bool Equals(object o)=>o is PreciseTerrainBorderKey k&&Equals(k);public override int GetHashCode()=>unchecked(((Axis*397^FixedWorld.GetHashCode())*397^AlongMin.GetHashCode())*397^AlongMax.GetHashCode());public static PreciseTerrainBorderKey[] For(TerrainCellBounds b)=>new[]{new PreciseTerrainBorderKey(0,b.MinX,b.MinZ,b.MaxZ),new PreciseTerrainBorderKey(0,b.MaxX,b.MinZ,b.MaxZ),new PreciseTerrainBorderKey(1,b.MinZ,b.MinX,b.MaxX),new PreciseTerrainBorderKey(1,b.MaxZ,b.MinX,b.MaxX)};}
